+            rsp_t response = {};
+            send(cmd, input, sizeof(req_t), nullptr, 0, &response, sizeof(response));
+            return response;
+        }
+    }
+
+    // queues the request of `cmd`; *response, if given, is written when the command completes
+    template <rpc_cmd cmd>
