+// ggml_nbytes on the wire values, false if it overflows
+static bool rpc_tensor_nbytes(const rpc_tensor & tensor, uint64_t & nbytes) {
+    nbytes = 0;
+    for (int i = 0; i < GGML_MAX_DIMS; i++) {
